// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 fundAmount, address attacker) public {
        fundAmount = bound(fundAmount, 1, 1 ether);
        vm.assume(attacker != address(this));

        Reverter reverter = new Reverter();

        vm.deal(address(this), fundAmount);
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent);

        c.sendMoney(address(reverter), fundAmount);

        vm.prank(attacker);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable { revert("fail"); }
    receive() external payable { revert("fail"); }
}
